def classify_outcome(status, elapsed_ms, timeout_ms, required_fields, data):
    if type(status) is not str or type(elapsed_ms) is not int or type(timeout_ms) is not int:
        raise TypeError('scalar_invalid')
    if status not in {'ok','unavailable','rate_limited','invalid','failed'}:
        raise ValueError('status_invalid')
    if elapsed_ms < 0 or timeout_ms <= 0:
        raise ValueError('time_invalid')
    if type(required_fields) is not tuple or type(data) is not dict:
        raise TypeError('container_invalid')
    if any(type(field) is not str for field in required_fields) or any(type(key) is not str for key in data):
        raise TypeError('field_invalid')
    if any(not field.strip() for field in required_fields) or len(set(required_fields)) != len(required_fields):
        raise ValueError('required_fields_invalid')
    if elapsed_ms > timeout_ms:
        return 'timeout'
    if status == 'ok':
        return 'ok' if set(required_fields).issubset(data) else 'invalid_response'
    return {'unavailable':'unavailable','rate_limited':'rate_limited','invalid':'invalid_response','failed':'dependency_failure'}[status]

def capped_backoff(attempt, base_ms, cap_ms):
    if type(attempt) is not int or type(base_ms) is not int or type(cap_ms) is not int:
        raise TypeError('backoff_input_invalid')
    if attempt < 1 or base_ms < 1 or cap_ms < 1:
        raise ValueError('backoff_value_invalid')
    if base_ms > cap_ms:
        raise ValueError('base_exceeds_cap')
    return min(cap_ms, base_ms * (2 ** (attempt - 1)))

def retry_delay(attempt, base_ms, backoff_cap_ms, retry_after_ms, retry_after_cap_ms):
    values = (attempt, base_ms, backoff_cap_ms, retry_after_cap_ms)
    if any(type(value) is not int for value in values):
        raise TypeError('retry_delay_input_invalid')
    if any(value < 1 for value in values) or base_ms > backoff_cap_ms:
        raise ValueError('retry_delay_value_invalid')
    if retry_after_ms is not None and type(retry_after_ms) is not int:
        raise TypeError('retry_after_invalid')
    if retry_after_ms is not None and retry_after_ms < 1:
        raise ValueError('retry_after_invalid')
    backoff = min(backoff_cap_ms, base_ms * (2 ** (attempt - 1)))
    if retry_after_ms is None:
        return backoff
    return max(backoff, min(retry_after_ms, retry_after_cap_ms))

def should_retry(outcome, attempt, max_attempts, circuit_state, operation_safe):
    if type(outcome) is not str or type(attempt) is not int or type(max_attempts) is not int or type(circuit_state) is not str or type(operation_safe) is not bool:
        raise TypeError('retry_decision_input_invalid')
    outcomes = {'ok','unavailable','rate_limited','timeout','invalid_response','dependency_failure','circuit_open'}
    if outcome not in outcomes or circuit_state not in {'closed','open','half_open'}:
        raise ValueError('retry_decision_value_invalid')
    if attempt < 1 or max_attempts < 1 or attempt > max_attempts:
        raise ValueError('attempt_invalid')
    transient = {'unavailable','rate_limited','timeout'}
    return operation_safe and outcome in transient and attempt < max_attempts and circuit_state != 'open'

def circuit_admission(state, now_ms, opened_at_ms, recovery_timeout_ms):
    if type(state) is not str or type(now_ms) is not int or type(recovery_timeout_ms) is not int:
        raise TypeError('circuit_input_invalid')
    if state not in {'closed','open','half_open'} or now_ms < 0 or recovery_timeout_ms < 1:
        raise ValueError('circuit_value_invalid')
    if state == 'open':
        if type(opened_at_ms) is not int:
            raise TypeError('opened_at_invalid')
        if opened_at_ms < 0 or opened_at_ms > now_ms:
            raise ValueError('opened_at_invalid')
        if now_ms - opened_at_ms < recovery_timeout_ms:
            return ('open', False)
        return ('half_open', True)
    if opened_at_ms is not None:
        raise ValueError('opened_at_only_when_open')
    return (state, True)

def circuit_failure(state, consecutive_failures, threshold, now_ms):
    if type(state) is not str or type(consecutive_failures) is not int or type(threshold) is not int or type(now_ms) is not int:
        raise TypeError('circuit_failure_input_invalid')
    if state not in {'closed','half_open'} or consecutive_failures < 0 or threshold < 1 or now_ms < 0:
        raise ValueError('circuit_failure_value_invalid')
    failures = consecutive_failures + 1
    if state == 'half_open' or failures >= threshold:
        return {'state':'open','consecutive_failures':failures,'opened_at_ms':now_ms}
    return {'state':'closed','consecutive_failures':failures,'opened_at_ms':None}

def circuit_success(state, consecutive_failures, opened_at_ms):
    if type(state) is not str or type(consecutive_failures) is not int:
        raise TypeError('circuit_success_input_invalid')
    if state not in {'closed','half_open'} or consecutive_failures < 0:
        raise ValueError('circuit_success_value_invalid')
    if state == 'closed' and opened_at_ms is not None:
        raise ValueError('closed_has_opened_at')
    if state == 'half_open':
        if type(opened_at_ms) is not int:
            raise TypeError('half_open_timestamp_invalid')
        if opened_at_ms < 0:
            raise ValueError('half_open_timestamp_invalid')
    return ('closed', 0, None)

def required_fields_present(required_fields, data):
    if type(required_fields) is not tuple or type(data) is not dict:
        raise TypeError('required_field_container_invalid')
    if any(type(field) is not str for field in required_fields) or any(type(key) is not str for key in data):
        raise TypeError('required_field_item_invalid')
    if any(not field.strip() for field in required_fields):
        raise ValueError('required_field_blank')
    if len(set(required_fields)) != len(required_fields):
        raise ValueError('required_field_duplicate')
    return set(required_fields).issubset(data)

def fallback_resolution(primary_code, fallback_name, data):
    if type(primary_code) is not str or type(fallback_name) is not str or type(data) is not dict:
        raise TypeError('fallback_input_invalid')
    if not primary_code.strip() or not fallback_name.strip():
        raise ValueError('fallback_name_blank')
    if any(type(key) is not str for key in data):
        raise TypeError('fallback_data_key_invalid')
    return {
        'status':'degraded',
        'code':'fallback_used',
        'selected_dependency':fallback_name,
        'data':dict(data),
        'warnings':('primary_dependency_failed','primary_code:'+primary_code,'degraded_fallback:'+fallback_name),
    }

def terminal_failure_code(outcome, failure_kind):
    if type(outcome) is not str or type(failure_kind) is not str:
        raise TypeError('failure_code_input_invalid')
    mapping = {
        'unavailable':'dependency_unavailable',
        'rate_limited':'rate_limited',
        'timeout':'timeout',
        'invalid_response':'invalid_response',
        'dependency_failure':'dependency_failure',
        'circuit_open':'circuit_open',
    }
    if outcome not in mapping or failure_kind not in {'transient','permanent'}:
        raise ValueError('failure_code_value_invalid')
    if failure_kind == 'transient' and outcome != 'circuit_open':
        return 'retry_exhausted'
    return mapping[outcome]

def register_idempotency(key, tenant, scenario, fingerprints):
    if type(key) is not str or type(tenant) is not str or type(scenario) is not str or type(fingerprints) is not dict:
        raise TypeError('idempotency_input_invalid')
    if not key.strip() or not tenant.strip() or not scenario.strip():
        raise ValueError('idempotency_blank')
    for known_key, value in fingerprints.items():
        if type(known_key) is not str or type(value) is not tuple or len(value) != 2 or any(type(item) is not str for item in value):
            raise TypeError('fingerprint_invalid')
    fingerprint = (tenant, scenario)
    known = fingerprints.get(key)
    if known is None:
        fingerprints[key] = fingerprint
        return 'accept'
    if known == fingerprint:
        return 'duplicate'
    raise ValueError('idempotency_key_conflict')

def lease_next(pending, in_flight, deliveries):
    if type(pending) is not list or type(in_flight) is not dict or type(deliveries) is not dict:
        raise TypeError('lease_container_invalid')
    if any(type(job) is not str for job in pending) or any(not job.strip() for job in pending) or len(set(pending)) != len(pending):
        raise ValueError('pending_invalid')
    if any(type(job) is not str or value is not True for job, value in in_flight.items()):
        raise TypeError('in_flight_invalid')
    if any(type(job) is not str or type(count) is not int for job, count in deliveries.items()):
        raise TypeError('deliveries_invalid')
    if any(count < 0 for count in deliveries.values()):
        raise ValueError('delivery_count_invalid')
    if not pending:
        return None
    job = pending[0]
    if job in in_flight:
        raise ValueError('job_already_in_flight')
    pending.pop(0)
    deliveries[job] = deliveries.get(job, 0) + 1
    in_flight[job] = True
    return job

