def acknowledge(job_id, result_job_id, idempotency_key, in_flight, results):
    if any(type(value) is not str for value in (job_id,result_job_id,idempotency_key)) or type(in_flight) is not dict or type(results) is not dict:
        raise TypeError('ack_input_invalid')
    if any(not value.strip() for value in (job_id,result_job_id,idempotency_key)):
        raise ValueError('ack_identifier_blank')
    if any(type(key) is not str or value is not True for key, value in in_flight.items()):
        raise TypeError('in_flight_invalid')
    if any(type(key) is not str or type(value) is not str for key, value in results.items()):
        raise TypeError('results_invalid')
    if in_flight.get(job_id) is not True:
        raise ValueError('job_not_leased')
    if result_job_id != job_id:
        raise ValueError('result_job_mismatch')
    if idempotency_key in results:
        raise ValueError('result_already_recorded')
    del in_flight[job_id]
    results[idempotency_key] = result_job_id
    return True

