def can_requeue(failure_kind, delivery_count, max_deliveries):
    if type(failure_kind) is not str or type(delivery_count) is not int or type(max_deliveries) is not int:
        raise TypeError('redelivery_input_invalid')
    if failure_kind not in {'transient','permanent'} or delivery_count < 1 or max_deliveries < 1 or delivery_count > max_deliveries:
        raise ValueError('redelivery_value_invalid')
    return failure_kind == 'transient' and delivery_count < max_deliveries

def dead_letter_record(job, code, delivery_count, dependency_attempt_count):
    if type(job) is not dict or type(code) is not str or type(delivery_count) is not int or type(dependency_attempt_count) is not int:
        raise TypeError('dead_letter_input_invalid')
    required = {'job_id','tenant_id','idempotency_key','scenario'}
    if set(job) != required or any(type(value) is not str for value in job.values()):
        raise ValueError('job_shape_invalid')
    if any(not value.strip() for value in job.values()) or not code.strip():
        raise ValueError('dead_letter_value_blank')
    if delivery_count < 1 or dependency_attempt_count < 0:
        raise ValueError('dead_letter_count_invalid')
    return {
        'job_id':job['job_id'],
        'tenant_id':job['tenant_id'],
        'scenario':job['scenario'],
        'code':code,
        'delivery_count':delivery_count,
        'dependency_attempt_count':dependency_attempt_count,
    }

