def summarize_batch(statuses):
    if type(statuses) is not tuple:
        raise TypeError('statuses_invalid')
    if any(type(status) is not str for status in statuses):
        raise TypeError('status_item_invalid')
    allowed = {'completed','degraded','dead_letter'}
    if any(status not in allowed for status in statuses):
        raise ValueError('status_value_invalid')
    return {
        'completed_count':statuses.count('completed'),
        'degraded_count':statuses.count('degraded'),
        'dead_letter_count':statuses.count('dead_letter'),
        'total':len(statuses),
    }

def ordered_results(job_ids, results):
    if type(job_ids) is not tuple or type(results) is not dict:
        raise TypeError('ordered_result_container_invalid')
    if any(type(job) is not str for job in job_ids) or any(not job.strip() for job in job_ids) or len(set(job_ids)) != len(job_ids):
        raise ValueError('job_ids_invalid')
    if any(type(job) is not str or type(status) is not str for job, status in results.items()):
        raise TypeError('result_item_invalid')
    if set(results) != set(job_ids):
        raise ValueError('result_coverage_invalid')
    allowed = {'completed','degraded','dead_letter'}
    if any(status not in allowed for status in results.values()):
        raise ValueError('result_status_invalid')
    return tuple(results[job] for job in job_ids)

def attempt_record(dependency, attempt, invoked, outcome, elapsed_ms, scheduled_backoff_ms, circuit_state_after):
    if type(dependency) is not str or type(outcome) is not str or type(circuit_state_after) is not str or type(attempt) is not int or type(invoked) is not bool or type(elapsed_ms) is not int or type(scheduled_backoff_ms) is not int:
        raise TypeError('attempt_input_invalid')
    if not dependency.strip() or not outcome.strip() or attempt < 1 or elapsed_ms < 0 or scheduled_backoff_ms < 0:
        raise ValueError('attempt_value_invalid')
    if circuit_state_after not in {'closed','open','half_open'}:
        raise ValueError('circuit_state_invalid')
    if not invoked and (elapsed_ms != 0 or scheduled_backoff_ms != 0):
        raise ValueError('non_invocation_has_timing')
    return {
        'dependency':dependency,
        'attempt':attempt,
        'invoked':invoked,
        'outcome':outcome,
        'elapsed_ms':elapsed_ms,
        'scheduled_backoff_ms':scheduled_backoff_ms,
        'circuit_state_after':circuit_state_after,
    }

def outcome_counts(attempts):
    if type(attempts) is not tuple:
        raise TypeError('attempts_invalid')
    allowed = ('ok','unavailable','rate_limited','timeout','invalid_response','dependency_failure','circuit_open')
    counts = {outcome:0 for outcome in allowed}
    for row in attempts:
        if type(row) is not dict:
            raise TypeError('attempt_invalid')
        if set(row) != {'dependency','outcome'}:
            raise ValueError('attempt_shape_invalid')
        if any(type(value) is not str for value in row.values()):
            raise TypeError('attempt_value_invalid')
        if not row['dependency'].strip() or row['outcome'] not in counts:
            raise ValueError('attempt_value_invalid')
        counts[row['outcome']] += 1
    return counts

